fn solve(x: i32) -> i32 {
    // Convert x to string to easily access digits and length
    let x_str = x.to_string();
    let first_digit = x_str.chars().next().unwrap().to_digit(10).unwrap() as i32;
    let length = x_str.len() as i32;
    
    // Calculate the score
    // Numbers before this digit: (first_digit - 1) * 10 presses total (1+2+3+4 = 10 per digit)
    let before_digit = (first_digit - 1) * 10;
    
    // Numbers of this digit before current length: 1+2+...+(length-1)
    let before_length = (1..length).sum::<i32>();
    
    // Add the current number's length
    before_digit + before_length + length
}